"use client"

import React, { useState, forwardRef } from "react";
import { CopyIcon, RefreshCwIcon, CheckIcon, Ellipsis, ThumbsUp, ThumbsDown } from "lucide-react";

import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";

type GeneratedAnswer = {
  className?: string;
  GeneratedAnswer?: string;
  hours?: string;
};

const GeneratedAnswer = forwardRef<HTMLDivElement, GeneratedAnswer>(({
  GeneratedAnswer,
  className,
  hours = "00:00",
  ...props
}, ref) => {
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    if (GeneratedAnswer) {
      navigator.clipboard.writeText(GeneratedAnswer);
      setCopied(true);
      setTimeout(() => setCopied(false), 1200);
    }
  };

  const handleLike = () => {};

  const handleDisLike = () => {};

  const handleRegenerate = () => {};

  return (
    <div ref={ref} className="flex flex-col w-full gap-2 max-w-lg" {...props}>
      <div className={cn("min-h-72 w-full", className)}>{GeneratedAnswer}</div>

      <div className="w-full flex justify-between items-center">
        <div>
          <span className="text-sm text-neutral-400">{hours}</span>
        </div>

        <div className="flex gap-2">
          <Button
            className={cn(
              "bg-transparent dark:hover:bg-neutral-200/40 px-1.5 py-0.5 md:p-2.5 dark:bg-neutral-700/20 hover:bg-neutral-200/40 relative transition-all duration-200",
              copied && "bg-green-100 "
            )}
            onClick={handleCopy}
            title="Copier"
            disabled={copied}
          >
            <span className="flex items-center justify-center transition-all duration-200">
              {copied ? <CheckIcon className="" /> : <CopyIcon />}
            </span>
          </Button>

          <Button
            className="bg-transparent dark:hover:bg-neutral-200/40 dark:bg-neutral-700/20 hover:bg-neutral-200/40 px-1.5 py-0.5 md:p-2"
            onClick={handleLike}
            title="like GeneratedAnswer"
          >
             <ThumbsUp className="h-3 w-3" />
          </Button>

          <Button
            className="bg-transparent dark:hover:bg-neutral-200/40  dark:bg-neutral-700/20 hover:bg-neutral-200/40 px-1.5 py-0.5 md:p-2"
            onClick={handleDisLike}
            title="like GeneratedAnswer"
          >

           <ThumbsDown className="h-3 w-3" />
          </Button>

          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button
                className="bg-transparent dark:hover:bg-neutral-200/40 dark:bg-neutral-700/20 hover:bg-neutral-200/40 px-1.5 py-0.5 md:p-2"
                onClick={handleRegenerate}
                title="regenerate"
              >
                <RefreshCwIcon />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent
              className={cn(
                "min-w-[12rem]",
                "border-black/10 mt-1 rounded-xl dark:border-white/10",
                "bg-neutral-100 dark:bg-neutral-900"
              )}
            >
              <DropdownMenuItem className="rounded-lg h-9 cursor-pointer hover:!bg-neutral-200 dark:hover:!bg-neutral-200/20 gap-2">
                Ajouter un commentaire
              </DropdownMenuItem>
              <DropdownMenuItem className="rounded-lg h-9 cursor-pointer hover:!bg-neutral-200 dark:hover:!bg-neutral-200/20 gap-2">
                Sans commentaire
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>

          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button
                className="bg-transparent dark:hover:bg-neutral-200/40 dark:bg-neutral-700/20 hover:bg-neutral-200/40 px-1.5 py-0.5 md:p-2"
                onClick={handleRegenerate}
                title="regenerate"
              >
                <Ellipsis />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent
              className={cn(
                "min-w-[12rem]",
                "border-black/10 mt-1 rounded-xl dark:border-white/10",
                "bg-neutral-100 dark:bg-neutral-900"
              )}
            >
              <DropdownMenuItem className="rounded-lg h-9 cursor-pointer hover:!bg-neutral-200 dark:hover:!bg-neutral-200/20 gap-2">
                Signaler un probleme
              </DropdownMenuItem>
              <DropdownMenuItem className="rounded-lg h-9 cursor-pointer hover:!bg-neutral-200 dark:hover:!bg-neutral-200/20 gap-2">
                Exporter en PDF
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>
    </div>
  );
});

GeneratedAnswer.displayName = 'GeneratedAnswer';
export default GeneratedAnswer;

import * as React from "react"
import { Slot } from "@radix-ui/react-slot"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-all disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4 shrink-0 [&_svg]:shrink-0 outline-none focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px] aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive",
  {
    variants: {
      variant: {
        default:
          "bg-primary text-primary-foreground shadow-xs hover:bg-primary/90",
        destructive:
          "bg-destructive text-white shadow-xs hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/40 dark:bg-destructive/60",
        outline:
          "border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:bg-input/30 dark:border-input dark:hover:bg-input/50",
        secondary:
          "bg-secondary text-secondary-foreground shadow-xs hover:bg-secondary/80",
        ghost:
          "hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default: "h-9 px-4 py-2 has-[>svg]:px-3",
        sm: "h-8 rounded-md gap-1.5 px-3 has-[>svg]:px-2.5",
        lg: "h-10 rounded-md px-6 has-[>svg]:px-4",
        icon: "size-9",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

function Button({
  className,
  variant,
  size,
  asChild = false,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
  }) {
  const Comp = asChild ? Slot : "button"

  return (
    <Comp
      data-slot="button"
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  )
}

export { Button, buttonVariants }

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

export const globalVariants = {
   variant: {
      default: "border bg-neutral-200/40 dark:bg-neutral-200/20 dark:hover:bg-neutral-200/40 text-black  dark:border-neutral-200/20  border-neutral-300/50 dark:text-neutral-200",
      ghost: "dark:hover:bg-neutral-700/40 dark:hover:bg-neutral-500/40 hover:bg-gray-200/40 bg-neutral-200/40 hover:bg-neutral-300/60 dark:bg-neutral-700 dark:text-gray-200",
      outline: "border border-neutral-300/40 dark:hover:bg-neutral-500/40 hover:bg-gray-200/40  dark:text-gray-200",
      none:"bg-none border-none",
    },
}
